import { Modal } from 'antd'
import popup_img from 'assets/images/popup.png'
import { useState } from 'react'

const PopupWelcome = () => {
    const [showModal,setShowModal] = useState(false)
    return (
        <Modal centered open width={350} footer={null} className='pop-up-welcome'>
            <div className='rounded-xl overflow-hidden relative'>
                <a href='https://t.me/ducks_earning' target='_blank'>
                    <img src={popup_img} alt='' className='object-cover' />
                </a>
            </div>
        </Modal>
    )
}

export default PopupWelcome
